const items = [];

export function add(title) {
  const item = { title, done: false };
  items.push(item);
  return item;
}

export function list() {
  return [...items];
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { add, list } from '../../src/todo/index.mjs';

test('新建后列表多一条', () => {
  add('买菜');
  assert.deepEqual(list(), [{ title: '买菜', done: false }]);
});
